        // ArrUnevenMaxBits is the longest wire path; align pads at worst case (SPEC §6.1).
        // ArrUnevenMaxBytes is rounded up to the 8-byte write-buffer granularity.
        public const int ArrUnevenMaxBits = 127;
        public const int ArrUnevenMaxBytes = 16;

        // The §5 zero form: all-zero storage; specified defaults live only in construction.
        public static void ZeroArrUneven(ref ArrUneven value)
        {
            value.Lead = 0;
            for (int i = 0; i < 3; i++)
            {
                ZeroUneven(ref value.Items[i]);
            }
            value.ItemsCount = 0;
            value.Tail = 0;
        }

        // batch form: stream state stays in registers across the body and End
        // publishes it — same wire bytes, same validation, same error model.
        public static bool WriteArrUneven(WriteStream stream, ref ArrUneven value)
        {
            WriteBatch batch = stream.BeginBatch();
            bool result = WriteArrUnevenBatch(ref batch, ref value);
            batch.End();
            return result;
        }

        // inline-only batch core — a real call would address-expose the batch
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool WriteArrUnevenBatch(ref WriteBatch batch, ref ArrUneven value)
        {
            if (!batch.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            Debug.Assert(value.ItemsCount >= 0 && value.ItemsCount <= 3, "value.ItemsCount out of range [0, 3]"); // the count guards the loop (§6.3); an out-of-contract count is caller error
            {
                uint offsetValue = (uint)(value.ItemsCount);
                if (!batch.SerializeBits(ref offsetValue, 2))
                {
                    return false;
                }
            }
            for (int i = 0; i < value.ItemsCount; i++)
            {
                if (!WriteUnevenBatch(ref batch, ref value.Items[i]))
                {
                    return false;
                }
            }
            if (!batch.SerializeBits(ref value.Tail, 3))
            {
                return false;
            }
            return true;
        }

        public static bool ReadArrUneven(ReadStream stream, ref ArrUneven value)
        {
            ReadBatch batch = stream.BeginBatch();
            bool result = ReadArrUnevenBatch(ref batch, ref value);
            batch.End();
            return result;
        }

        // inline-only batch core — a real call would address-expose the batch
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool ReadArrUnevenBatch(ref ReadBatch batch, ref ArrUneven value)
        {
            if (!batch.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            if (!batch.SerializeInt(ref value.ItemsCount, 0, 3)) // the count guards the loop (§6.3)
            {
                return false;
            }
            for (int i = 0; i < value.ItemsCount; i++)
            {
                if (!ReadUnevenBatch(ref batch, ref value.Items[i]))
                {
                    return false;
                }
            }
            if (!batch.SerializeBits(ref value.Tail, 3))
            {
                return false;
            }
            return true;
        }

        // RegainAfterAlignMaxBits is the longest wire path; align pads at worst case (SPEC §6.1).
        // RegainAfterAlignMaxBytes is rounded up to the 8-byte write-buffer granularity.
        public const int RegainAfterAlignMaxBits = 172;
        public const int RegainAfterAlignMaxBytes = 24;

        // The §5 zero form: all-zero storage; specified defaults live only in construction.
        public static void ZeroRegainAfterAlign(ref RegainAfterAlign value)
        {
            value.Lead = 0;
            value.Items[..].Clear();
            value.ItemsCount = 0;
            value.S[..].Clear();
            value.SLength = 0;
            value.P = 0;
            value.Q = 0;
            value.R = 0;
            value.Tail = 0;
        }

        public static bool WriteRegainAfterAlign(WriteStream stream, ref RegainAfterAlign value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            Debug.Assert(value.ItemsCount >= 0 && value.ItemsCount <= 3, "value.ItemsCount out of range [0, 3]"); // the count guards the loop (§6.3); an out-of-contract count is caller error
            {
                uint offsetValue = (uint)(value.ItemsCount);
                if (!stream.SerializeBits(ref offsetValue, 2))
                {
                    return false;
                }
            }
            for (int i = 0; i < value.ItemsCount; i++)
            {
                Debug.Assert(value.Items[i] <= 8191, "value.Items[i] out of range [0, 8191]");
                {
                    uint offsetValue = (uint)(value.Items[i]);
                    if (!stream.SerializeBits(ref offsetValue, 13))
                    {
                        return false;
                    }
                }
            }
            Debug.Assert(value.SLength >= 0 && value.SLength <= 4, "value.SLength out of range [0, 4]"); // the length guards the slice (§6.3); an out-of-contract length is caller error
            {
                uint offsetValue = (uint)(value.SLength);
                if (!stream.SerializeBits(ref offsetValue, 3))
                {
                    return false;
                }
            }
            if (!stream.SerializeBytes(value.S[..value.SLength]))
            {
                return false;
            }
            {
                // flat run: 84 bits in 2 chunk(s) — the field placement is folded
                ulong f0 = ((ulong)value.P) & 0xffffffffUL;
                ulong f1 = ((ulong)value.Q) & 0x1fffffffUL;
                ulong f2 = ((ulong)value.R) & 0x7ffffUL;
                ulong f3 = ((ulong)value.Tail) & 0xfUL;
                ulong w0 = f0 | (f1 << 32) | (f2 << 61);
                if (!stream.SerializeBits64(ref w0, 64))
                {
                    return false;
                }
                uint w1 = (uint)((f2 >> 3) | (f3 << 16));
                if (!stream.SerializeBits(ref w1, 20))
                {
                    return false;
                }
            }
            return true;
        }

        public static bool ReadRegainAfterAlign(ReadStream stream, ref RegainAfterAlign value)
        {
            if (!stream.SerializeBits(ref value.Lead, 5))
            {
                return false;
            }
            if (!stream.SerializeInt(ref value.ItemsCount, 0, 3)) // the count guards the loop (§6.3)
            {
                return false;
            }
            for (int i = 0; i < value.ItemsCount; i++)
            {
                {
                    int rangeValue = 0;
                    if (!stream.SerializeInt(ref rangeValue, 0, 8191))
                    {
                        return false;
                    }
                    value.Items[i] = (ushort)rangeValue;
                }
            }
            if (!stream.SerializeInt(ref value.SLength, 0, 4)) // the length guards the slice (§6.3)
            {
                return false;
            }
            if (!stream.SerializeBytes(value.S[..value.SLength]))
            {
                return false;
            }
            for (int utf8Index = 0; utf8Index < value.SLength;)
            {
                int utf8Lead = value.S[utf8Index++];
                if (utf8Lead < 0x80) continue;
                int utf8Remaining, utf8Point;
                if ((utf8Lead & 0xE0) == 0xC0) { utf8Remaining = 1; utf8Point = utf8Lead & 0x1F; }
                else if ((utf8Lead & 0xF0) == 0xE0) { utf8Remaining = 2; utf8Point = utf8Lead & 0x0F; }
                else if ((utf8Lead & 0xF8) == 0xF0) { utf8Remaining = 3; utf8Point = utf8Lead & 0x07; }
                else return false; // malformed UTF-8 lead (SPEC §4.7)
                if (utf8Remaining > value.SLength - utf8Index) return false;
                for (int utf8Part = 0; utf8Part < utf8Remaining; utf8Part++)
                {
                    int utf8Byte = value.S[utf8Index++];
                    if ((utf8Byte & 0xC0) != 0x80) return false;
                    utf8Point = (utf8Point << 6) | (utf8Byte & 0x3F);
                }
                if (utf8Remaining == 1 && utf8Point < 0x80) return false;
                if (utf8Remaining == 2 && (utf8Point < 0x800 || (utf8Point >= 0xD800 && utf8Point <= 0xDFFF))) return false;
                if (utf8Remaining == 3 && (utf8Point < 0x10000 || utf8Point > 0x10FFFF)) return false;
            }
            for (int i = 0; i < value.SLength; i++)
            {
                if (value.S[i] == 0) // an interior null is content the read refuses (SPEC §4.7)
                {
                    return false;
                }
            }
            {
                // flat run: 84 bits in 2 chunk(s) — one bounds check per chunk,
                // one sticky-error test for the whole run
                ulong c0 = 0;
                stream.SerializeBits64(ref c0, 64);
                ulong c1 = 0;
                stream.SerializeBits64(ref c1, 20);
                if (!stream.Ok)
                {
                    return false;
                }
                ulong v0 = c0 & 0xffffffffUL;
                value.P = (uint)v0;
                ulong v1 = (c0 >> 32) & 0x1fffffffUL;
                value.Q = (uint)v1;
                ulong v2 = ((c0 >> 61) | (c1 << 3)) & 0x7ffffUL;
                value.R = (uint)v2;
                ulong v3 = (c1 >> 16) & 0xfUL;
                value.Tail = (uint)v3;
            }
            return true;
        }
    }

